// === Tab: sketch154493 ===
let pg;
let nbPartsPerLetter = 180;
let textCol = color(255, 0, 0);
let MARGIN = 0;
let STILL = 0;
let MOUSE = 1;
let BOMB  = 2;
let mode = STILL;
let word = "The Exploded Design School Show";
let parts;
let nbParts;

function setup()
{
  createCanvas(550, 400);
  process(word);
}

function process(p_word)
{
  nbParts = nbPartsPerLetter * p_word.length();
  parts = new Array(nbParts);
  pg = createGraphics(width, height);
  pg.beginShape();
  pg.textSize(70);
  pg.fill(textCol);
  pg.text(p_word, MARGIN + 75, MARGIN + 120, width - MARGIN - 60, height - MARGIN - 60);
  pg.endShape();

  pg.loadPixels();
  for (i = 0; i < nbParts; i ++)
  {
    parts[i] = new Particle();
  }
  pg.updatePixels();
}

function draw()
{
  fill(120);
  stroke(20, 255);  
  rect(MARGIN - 4, MARGIN - 4, width-2*MARGIN+8, height-2*MARGIN+8); 

  stroke(0, 30);
  for (i = 0; i < nbParts; i ++)
  {
    parts[i].update(mode);
    parts[i].draw();
  }
}

function mousePressed()
{
  if (mouseButton == LEFT)
  {
    mode = MOUSE;
  } else if (mouseButton == RIGHT)
  {
    for (i = 0; i < nbParts; i ++)
    {
      parts[i].update(BOMB);
    }
  }
}

function mouseReleased()
{
  mode = STILL;
}

function keyPressed()
{
  if (key != CODED)
  {
    word += new String(key);
    if (word.length() > 9)
    {
      word = word.substring(1);
    }
    process(word);
  }
}

class Particle
{
  FRICTION1 = .98;
  G1 = .05;
  CALM1 = .92;
  FRICTION2 = .98;
  G2 = 4;
  CALM2 = .96;
  let MASS = random(4, 9);
  let col = color(random(140, 230), random(50, 120), random(34, 76));
  let rad = random(2, 6);
  pos;
  speed;
  origin;
  found = false;

  constructor()
  {
    speed = new PVector(0, 0);
    while (!found)
    {
      let x = int(random)(width);
      let y = int(random)(height);
      if (pg.pixels[y * width + x] == textCol)
      {
        pos = new PVector(x, y);
        origin = pos.get();
        found = true;
      }
    }
  }

  function update(p_mode)
  {
    let target;
    let l;
    switch(p_mode)
    {
    case MOUSE:
      target = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
      target.sub(pos);
      l = target.mag() < 60 ? 500 : target.mag();
      target.normalize();
      target.mult(FRICTION2 * G2 * MASS / (sqrt(l)));
      speed.add(target);
      speed.mult(CALM2);
      break;
    case STILL:
      target = origin.get();
      target.sub(pos);
      target.limit(10);
      target.mult(FRICTION1 * G1 * MASS);
      speed.add(target);
      speed.mult(CALM1);
      break;
    case BOMB:
      target = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
      target.sub(pos);
      target.limit(70);
      l = target.mag();
      target.mult(-40 / l);
      speed = target.get();
      break;
    }
  }

  function draw()
  {
    pos.add(speed);
    if (pos.x < MARGIN)
    {
      pos.x = MARGIN;
      speed.x *= -1;
    } else if (pos.x > width - MARGIN)
    {
      pos.x = width - MARGIN;
      speed.x *= -1;
    }
    if (pos.y < MARGIN)
    {
      pos.y = MARGIN;
      speed.y *= -1;
    } else if (pos.y > height - MARGIN)
    {
      pos.y = height - MARGIN;
      speed.y *= -1;
    }
    fill(col, 255);
    ellipse(pos.x, pos.y, rad, rad);
  }
}

